csui.define('d2/utils/vdoc.default.actionitems',[
  'nuc/lib/underscore',
  'nuc/models/actionitems',
  'd2/models/virtual.document.children',
  // Load and register external default action rules
  'csui-ext!d2/utils/vdoc.default.actionitems'
], function (_, ActionItemCollection, VirtualDocumentChildren, extraActions) {
  'use strict';

  var defaultActionItems = new ActionItemCollection([
    // Default is going to be the view vdoc command
    {
      sequence: 10,
      signature: 'D2-ViewVDoc',
      decides: function (node) {
        return node && (node.collection instanceof VirtualDocumentChildren);
      }
    }
  ]);

  if (extraActions) {
    defaultActionItems.add(_.flatten(extraActions, true));
  }

  return defaultActionItems;

});