csui.define('d2/widgets/d2collections.perspective/d2collections.perspective.view',[
    'd2/widgets/d2collections.perspective/d2collections.perspective.widgettable.view',
    'd2/widgets/widget.container/perspective.table.container.view',
    'd2/utils/widget.constants'
], function (D2CollectionPerspectiveView, PerspectiveTableContainer, WidgetConstants) {
    'use strict';

    /*
        The content of this file are moved to d2collections.perspective.widgettable.view as part of changes done in 23.4 for table preferences persistent.
        Now, this current file (d2collections.perspective.view.js) is responsible for fetching the column preferences and then load the table view.
     */
    return PerspectiveTableContainer.extend({
        constructor: function D2CollectionTableView(/* options */) {
            PerspectiveTableContainer.prototype.constructor.apply(this, arguments);
        },

        getWidgetViewClass: function () {
            return D2CollectionPerspectiveView;
        },

        getWidgetType: function(){
          return WidgetConstants.D2.COLLECTIONS;
        },

        resolveDataForTable: function () {
            return this.checkDataFetchedWithContext();
        }
    });
})
;