csui.define('d2/widgets/task.details/task.additional.panels',[
  'nuc/lib/underscore',
  'nuc/lib/backbone',
  'd2/widgets/task.details/impl/task.working.files/task.working.files.view',
  'd2/widgets/task.details/impl/task.supporting.files/task.supporting.files.view',
  'd2/widgets/task.details/impl/task.notes/task.notes.view',
  'i18n!d2/widgets/task.details/impl/nls/lang',
  // Load extra panels to be added to the built-in dropdown tabs
  'csui-ext!d2/widgets/task.details/task.additional.panels',
  'd2/sdk/widgets/task.details.panel/task.details.panel.views'
], function (_, Backbone, TaskWorkingFilesView,
             TaskSupportingFilesView, TaskNotesView, lang, extraPanels, sdkPanelsArray) {

  var PanelModel = Backbone.Model.extend({

    defaults: {
      sequence: 100,
      title: null,
      name: '',
      contentView: null,
      contentViewOptions: null
    },

    constructor: function PanelModel(/*attributes, options*/) {
      Backbone.Model.prototype.constructor.apply(this, arguments);
    }

  });

  var PanelCollection = Backbone.Collection.extend({

    model: PanelModel,
    comparator: "sequence",

    constructor: function PanelCollection(/*models, options*/) {
      Backbone.Collection.prototype.constructor.apply(this, arguments);
    }

  });

  var taskAdditionalPanels = new PanelCollection([
    {
      title: lang.defaultTitleAdditionalPanelWorkingFiles,
      name: 'working',
      sequence: 10,
      contentView: TaskWorkingFilesView
    }, {
      title: lang.defaultTitleAdditionalPanelSupportingFiles,
      name: 'supporting',
      sequence: 20,
      contentView: TaskSupportingFilesView
    }, {
      title: lang.defaultTitleAdditionalPanelNotes,
      name: 'notes',
      sequence: 30,
      contentView: TaskNotesView
    }
  ]);

  if (extraPanels) {
    taskAdditionalPanels.add(_.flatten(extraPanels, true));
    // assign default name to panels that are not having the 'name' field yet
    var counter = 1;
    taskAdditionalPanels.forEach(function (model) {
      // name can't be empty to be able to save the metadata view state in the url.
      if (!model.get('name')) {
        model.set('name', 'unnamed_panel' + counter, {silent: true});
        counter++;
      }
    });
  }

  if(_.isArray(sdkPanelsArray) && sdkPanelsArray.length > 0) {
    sdkPanelsArray.forEach(function(panel) {
      taskAdditionalPanels.add(new PanelModel(panel));
    });
  }

  return taskAdditionalPanels;

});
