csui.define('d2/server.adaptors/models/esoc/comment.model.mixin',[
  "nuc/lib/jquery",
  "nuc/lib/backbone",
  "nuc/lib/underscore",
  'nuc/utils/url',
  'd2/utils/rest.linkrels',
  'd2/utils/constants'
], function ($, Backbone, _, Url, RestLinkrels, constants) {
  'use strict';

  return {
    mixin: function (prototype) {
      return _.extend(prototype, {
        makeServerAdaptor: function (/*options*/) {
          return this;
        },
        sync: function (method, model, options) {
          switch (method) {
            case 'create':
              _.extend(options, {
                contentType: constants.MediaTypes.DCTM_JSON,
                data: JSON.stringify({
                  'content-value': options.jsonFormData.status
                }),
                url: RestLinkrels.getLink(options.currentNodeModel.get('links'),
                                                              RestLinkrels.COMMENTS)
              });
              break;
            case 'delete':
              _.extend(options, {
                url: Url.appendQuery(RestLinkrels.getLink(model.get('links'), RestLinkrels.DELETE), Url.combineQueryString({'parent-id': model?.collection?.currentNodeModel.get('id')}))
              });
              break;
          }

          return Backbone.Collection.prototype.sync.apply(this, arguments);
        }
      });
    }
  };

});