csui.define('d2/commands/tableview.close',[
  'nuc/lib/underscore',
  'nuc/lib/jquery',
  'csui/models/command',
  'i18n!d2/commands/nls/localized.strings'
], function (_, $, CommandModel, lang) {
  'use strict';

  var TableViewClose = CommandModel.extend({
    defaults: {
      signature: 'D2-TableViewClose',
      name: lang.CommandVDocTableViewClose,
      scope: 'single'
    },

    enabled: function (/*status, options*/) {
      return true;
    },

    execute: function (status/*, options*/) {
      var deferred = $.Deferred();

      if(status && status.originatingView) {
        status.originatingView.dialog.kill();
      }

      return deferred.resolve().promise();
    }
  });

  return TableViewClose;
});
