/* eslint-disable no-unused-vars */
csui.define('d2/widgets/splitview.widgets/virtual.document.edit.view',[
  'require',
  'nuc/lib/jquery',
  'nuc/lib/underscore',
  'nuc/utils/url',
  'd2/widgets/virtual.document.explorer/virtual.document.structure.view',
  'd2/widgets/virtual.document.explorer/vd.treenode.icon.view',
  'd2/utils/vdoc.utils',
  'd2/utils/rest.linkrels',
  'd2/utils/constants',
  "csui/utils/commands",
  'csui/models/fileuploads',
  'i18n!d2/commands/nls/localized.strings',
  'css!d2/controls/tree/impl/node.tree',
  'css!d2/widgets/virtual.document.explorer/impl/virtual.document.structure',
  'dctmw/lib/fancytree/jquery.fancytree.table',
  'dctmw/lib/fancytree/jquery.fancytree.dnd5',
  'd2/widgets/virtual.document.explorer/impl/fancytree.ext.vdoc'
], function (require,  $, _, Url, VDocStructureView, TreeViewWithNodeIcon, 
  vdUtil, RestLinkrels, constants, Commands, UploadFileCollection, lang) {
  'use strict';

  var VDocSplitView = VDocStructureView.extend({
    className: 'd2-tree-panel d2-vd-structure d2-vd-edit-structure',

    constructor: function VDocSplitView(options){
      options = options || {};
      this.isVDEditView = true;
      VDocSplitView.__super__.constructor.call(this,options);
    },

    _renderVDTree: function () {
      let options =  {}
      options.showAdditionalColumns = true;
      options.snapshotView= this.snapshotView;

      if (!this.$el.parent().length || !this.collection.fetched || this.isBusy) {
        return;
      }

      this.trigger('render:begin');
      if (!this.treeView) {
        this.treeView = new TreeViewWithNodeIcon(_.extend(this._buildTreeOptions(options), options));
        this.isBusy = true;
        this.treeRegion.show(this.treeView);
        this.treeView.$el.off(this.evtIdInlineMenuCreate).on(this.evtIdInlineMenuCreate, 'tr', _.throttle(this._createInlineMenu.bind(this), 300));
        this.treeView.$el.off(this.evtIdInlineMenuDestroy).on(this.evtIdInlineMenuDestroy, 'tr', this._destroyInlineMenu.bind(this));
      } else {
        this.blockActions();
        this.treeView.tree.reload().always(this.unblockActions.bind(this));
      }
    },
   
    getDnD: function() {
      let parentDnDOptions = VDocSplitView.__super__.getDnD.call(this);
      var me = this;
      parentDnDOptions.preventForeignNodes = false;

      parentDnDOptions.dragEnter = function (node, data) {
        var selectedNodes = data.tree.getSelectedNodes(),
          allowDrop = true;

        if (node === data.tree.getFirstChild()) {
          allowDrop =  true;
        } else if (_.contains(selectedNodes, data.otherNode)) {
          allowDrop = !_.contains(selectedNodes, node); //self drop
          //Check if the node being dropped on has any ancestor as one of the nodes being dropped
          allowDrop && $.each(selectedNodes, function (index, selectedNode) {
            if (_.contains(me._fetchAllParentNodes(node), selectedNode)) {
              allowDrop = false;
              return false;
            }
          });
        }
        return allowDrop && data.otherNode !== node && !me.options.isForComparing;
      };

      parentDnDOptions.dragDrop = function (node, data) {
        if (data.otherNode) {
          var selectedNodes = data.tree.getSelectedNodes(),
          samePosition = false,
          setSelected = true;

          if (!_.contains(selectedNodes, data.otherNode)) {
            selectedNodes = [data.otherNode];
            setSelected = false;
            //We check the whether the drop made will result in the node being in the same position and do not make the drop
            //The check could not be done on the drag enter level because it requires the hitmode, which is set after drag enter - US
            samePosition = ((node.getPrevSibling() === data.otherNode && data.hitMode === 'before') || (node.getNextSibling() === data.otherNode && data.hitMode === 'after')) && me.dropOver === false;
          } else {
            $.each(selectedNodes, function (index, selectedNode) {
              if (node.getNextSibling() === selectedNode && data.hitMode === 'after' && me.dropOver === false) {
                samePosition = true;
                return false;
              }
            });
          }

          if (!samePosition) {
            me.blockActions();
            me._performMoveAction(node, selectedNodes, data).done(function (result, targetNode) {
              if (setSelected) {
                me._setSelectedNodes(selectedNodes, targetNode);
              }
              me._checkNodeStatus(selectedNodes, result);
              me.unblockActions();
            }).fail(function (errMessage) {
              _.each(selectedNodes, function (selectedNode) {
                selectedNode.errorMessage = errMessage;
              });
              me._showErrorMessage(selectedNodes, 0);
              me.unblockActions();
            });
          }
        } else {
          // handle the nodes dragged from outside the fancytree
          var draggedData = JSON.parse(data.dataTransfer.getData('draggedData'));
          me.blockActions();
          me.editVD(node, data, JSON.parse(data.dataTransfer.getData('draggedData')), me.dropOver).done(function(res) {
            me._showEditVdStatus(res, draggedData);
            me.unblockActions();
          }).fail(function(errMessage) {
            me.unblockActions();
            csui.require([
              'd2/controls/globalmessage/globalmessage'
            ], function (GlobalMessage) {

              GlobalMessage.showMessage("error", errMessage);
            });
          });
        }
      }

      return parentDnDOptions;
    },


    _showEditVdStatus: function (status, draggedData) {
      if(!status || !status['operation-status']) return;
      let operationStatus = status['operation-status'];
      var queueItems = draggedData.nodes.map(function (item) {
        let status = operationStatus.find(stat => item['i_chronicle_id'] === stat['chronicle-id']);
        return {
          name: item.name,
          state: status['rest-error'] ? 'rejected' : 'resolved',
          errorMessage: status['rest-error']?.message,
          count: 1,
          total: 1,
        };
      });

      var nodeCollection = new UploadFileCollection(queueItems, {connector: this.connector});

      csui.require([
        'd2/controls/globalmessage/globalmessage'
      ], function (GlobalMessage) {
        GlobalMessage.showProgressPanel(nodeCollection, {
          oneFileSuccess: lang.AddVDOneItemSuccessMessage,
          multiFileSuccess: lang.AddVDManyItemsSuccessMessage,
          oneFileFailure: lang.AddVDOneItemFailureMessage,
          multiFileOneFailure: lang.AddVDManyItemsOneFailureMessage,
          multiFileFailure: lang.AddVDManyItemsFailureMessage
        });
      });
    },

    _setDropMarkerWidth: function (node) {
      var dropMarker = $('body').find('#fancytree-drop-marker');
      if (dropMarker && !dropMarker.is(":hidden")) {
        document.documentElement.style.setProperty("--vd-dropover-pos-left", `${node.tr.getBoundingClientRect().left}px`);
        dropMarker.css("width", parseInt($(node.tr).css("width")));
      }
    },

    editVD(node, data, dragData, dropOver) {
      let parent;
      if(dropOver || node.isTopLevel()) {
        parent = data.node.data.origNode;
        if(dragData.nodes.length == 1 && !node.isTopLevel()) {
          this.unblockActions();
          let replaceAddVdocCmd = Commands.get('D2-AddReplaceVdoc');
          return replaceAddVdocCmd.execute({
            'dragData': dragData,
            'targetNode': parent,
            "data": data
          }).done((res) => {
            this._refreshNodes([data.node.parent]);
          });
        } else {
          return this.addNodeToVd(node, parent, dragData.nodes, false);
        }
      } else {
        parent = data.node.parent.data.origNode;
        return this.addNodeToVd(node, parent, dragData.nodes, true, data.hitMode);
      }
    },

    addNodeToVd(node, parentNode, childNodes, performOrdering, hitMode) {
      let href = RestLinkrels.getLink(parentNode.get('links'), RestLinkrels.ADD_VIRTUAL_DOCUMENT_NODES),
          deferred = $.Deferred(),
          qParams = {},
          payload = {},
          me = this;
      qParams['inline'] = true;
      qParams['suppress-checkout-warning'] = true;
      payload['virtual-document-nodes'] = childNodes.map(item => {return {"chronicle-id": item['i_chronicle_id']}});
      href = Url.appendQuery(href, Url.combineQueryString(qParams));
      var nodesToRefresh = node.isTopLevel()? [node]: me._fetchAllImmediateParents([node]);
      $.ajax(parentNode.connector.extendAjaxOptions({
        url: href,
        type: 'POST',
        contentType: constants.MediaTypes.DCTM_JSON,
        data: JSON.stringify(payload),
        success: function (result) {
          if(performOrdering && !node.isLastSibling()) {
            me.orderTheAddedVDNodes(result, childNodes, node, parentNode, hitMode);
          }
          me._refreshNodes(nodesToRefresh).then(function () {
            if (node.isTopLevel()) node.setExpanded();
            deferred.resolve(result, node.parent);
          });
        },
        error: function (result) {
          deferred.reject(result.responseJSON.message);
        }
      }));

      return deferred.promise();
    },

    orderTheAddedVDNodes: function(result, childNodes, node, parentNode, hitMode){
      let me = this;
      let payload = {"virtual-document-nodes": []},
          beforeNodeRelationId, targetParentId;
      payload["virtual-document-nodes"] = childNodes.map(item => {
        let relation = result.entries.find(entry => entry.content.properties.i_chronicle_id === item['i_chronicle_id']);
        return {"relation-id": relation.content["relation-id"]};
      });
      beforeNodeRelationId = (hitMode === 'before')? 
                              vdUtil.getVDRelationId(node.data.origNode):
                              vdUtil.getVDRelationId(node.getNextSibling().data.origNode);
      targetParentId = parentNode.get('id');
      let href = RestLinkrels.getLink(parentNode.get('links'), RestLinkrels.VD_MOVE_NODES),
          qParams = {"inline": true, 'target-parent-id': targetParentId, 'insert-before-node': beforeNodeRelationId},
          deferred = $.Deferred(),
          nodesInvolved = [node],
          nodesToRefresh = this._fetchAllImmediateParents(nodesInvolved);
      href = Url.appendQuery(href, Url.combineQueryString(qParams));
      $.ajax(node.data.origNode.connector.extendAjaxOptions({
        url: href,
        type: 'PATCH',
        contentType: constants.MediaTypes.DCTM_JSON,
        data: JSON.stringify(payload),
        success: function (result) {
          me._refreshNodes(nodesToRefresh).then(function () {
            deferred.resolve(result, node.parent);
          });
        },
        error: function (result) {
          deferred.reject(result.responseJSON.message);
        }
      }));

      return deferred.promise();
    },

    _adjustVersionDisplay: function () {
      if (this.displayVersionColumn || this.isVDEditView) {
        this.$el.addClass('show-versions');
      } else {
        this.$el.removeClass('show-versions');
      }
    },
    
  })
  return VDocSplitView;
});