csui.define('d2/overrides/csui/controls/item.title/impl/dropdown.menu/dropdown.menu.view',[
  'require',
  'nuc/lib/underscore',
  'nuc/models/nodes',
  'csui/utils/commandhelper',
  'nuc/utils/log'
], function (require, _, NodeCollection, CommandHelper, log) {
  'use strict';

  //TODO: Remove this override once CSUI starts sending commandData along with status for item title dropdown menu
  csui.require(['csui/controls/item.title/impl/dropdown.menu/dropdown.menu.view'], function (DropdownMenuView) {
    DropdownMenuView.prototype._triggerMenuItemAction = function (toolItemView, args) {
      this.ui.dropdownToggle.binf_dropdown('toggle');  // close the dropdown menu before triggering the event

      var toolItem = args.toolItem;
      var signature = toolItem.get("signature");
      var command = this.commands.get(signature);
      var status = {
        context: this.options.context,
        nodes: new NodeCollection([this.model]),
        container: this.model,
        originatingView: this.options.originatingView,
        data: toolItem.get('commandData') || {}
      };
      try {
        // If the command was not found and the toolitem is executable, it is
        // a developer's mistake.
        if (!command) {
          throw new Error('Command "' + signature + '" not found.');
        } else if (_.isFunction(command.execute)) {
          var promise = command.execute(status);
          CommandHelper.handleExecutionResults(
            promise, {
              command: command,
              suppressSuccessMessage: status.suppressSuccessMessage,
              suppressFailMessage: status.suppressFailMessage
            });
        } else {
          this.trigger(signature.toLowerCase(), this);
        }
      } catch (error) {
        log.warn('Executing the command "{0}" failed.\n{1}',
          command.get('signature'), error.message) && console.warn(log.last);
      }
    }
  });
});