csui.define('d2/server.adaptors/models/esoc/tablecell.model.mixin',[
  'nuc/lib/underscore',
  'nuc/lib/jquery'
], function (_, $) {
  'use strict';

  return {
    mixin: function (prototype) {
      return _.extend(prototype, {
        makeServerAdaptor: function (/*options*/) {
          return this;
        },

        sync: function (method, model, options) {
          var deferred = $.Deferred();
          options = _.defaults({parse: false}, options);
          this.trigger('request', this, {}, options);
          setTimeout(function () {
            var response = {
              available_settings: {
                ttachementsEnabled: true,
                commentingOpen: true,
                commentsEnabled: true,
                CSID: this.get('id'),
                likesEnabled: false,
                pulseEnabled: true,
                shortcutsEnabled: true,
                taggingEnabled: false,
                threadingEnabled: true
              }
            };
            options.success.call(options.context, {}, 'success', response);
            deferred.resolve(response);
          }.bind(this), 1);
          return deferred.promise();
        }
      });
    }
  };

});
